*{box-sizing:border-box}
body{font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;margin:0;background:var(--bg);color:#1a1a1e}
button{font-family:inherit}
.muted{color:var(--muted)} .small{font-size:12px}

/* header */
.top{background:#fff;border-bottom:1px solid var(--line);padding:16px 22px}
.topbar{display:flex;align-items:center;justify-content:space-between;max-width:1040px;margin:0 auto 12px}
